import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
export default class ListVotersModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = true;
    app.store.find('polls', this.attrs.poll.id(), {
      include: 'votes,votes.user,votes.option'
    }).then(() => this.loading = false).finally(() => m.redraw());
  }
  className() {
    return 'Modal--medium VotesModal';
  }
  title() {
    return app.translator.trans('fof-polls.forum.votes_modal.title');
  }
  content() {
    const options = this.attrs.poll.options();
    return m("div", {
      className: "Modal-body"
    }, this.loading ? m(LoadingIndicator, null) : options.map(this.optionContent.bind(this)));
  }
  optionContent(opt) {
    const votes = (this.attrs.poll.votes() || []).filter(v => opt.id() === v.option().id());
    return m("div", {
      className: "VotesModal-option"
    }, m("h3", null, this.optionAnswer(opt) + ':'), votes.length ? m("div", {
      className: "VotesModal-list"
    }, votes.map(this.voteContent.bind(this))) : m("h4", null, app.translator.trans('fof-polls.forum.modal.no_voters')));
  }
  optionAnswer(opt) {
    return opt.answer();
  }
  voteContent(vote) {
    const user = vote.user();
    const attrs = user && {
      href: app.route.user(user)
    };
    return m(Link, attrs, m(Avatar, {
      user: user
    }), " ", username(user));
  }
}
flarum.reg.add('fof-polls', 'forum/components/ListVotersModal', ListVotersModal);